ALTER TABLE campaigns ADD COLUMN health_set_by_id TEXT REFERENCES operators(id);
ALTER TABLE risks ADD COLUMN resolved_at INTEGER;
ALTER TABLE risks ADD COLUMN resolved_by_id TEXT REFERENCES operators(id);
ALTER TABLE decisions ADD COLUMN supersedes_id TEXT REFERENCES decisions(id);
ALTER TABLE automations ADD COLUMN shipped_key TEXT;
CREATE UNIQUE INDEX launch_automation_shipped_key ON automations(shipped_key);
ALTER TABLE automation_runs ADD COLUMN trigger_key TEXT;
ALTER TABLE automation_runs ADD COLUMN definition_json TEXT;
ALTER TABLE automation_runs ADD COLUMN cause_run_ids_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE automation_runs ADD COLUMN retry_of TEXT;
CREATE UNIQUE INDEX launch_run_trigger ON automation_runs(automation_id,definition_version,trigger_key) WHERE retry_of IS NULL;
CREATE TABLE launch_custom_fields(id TEXT PRIMARY KEY,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,version INTEGER NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,options_json TEXT NOT NULL);
CREATE TABLE launch_custom_values(id TEXT PRIMARY KEY,field_id TEXT NOT NULL REFERENCES launch_custom_fields(id) ON DELETE CASCADE,campaign_id TEXT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,value_json TEXT NOT NULL,UNIQUE(field_id,campaign_id));
CREATE TABLE launch_readiness(id TEXT PRIMARY KEY,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,version INTEGER NOT NULL,milestone_id TEXT NOT NULL REFERENCES milestones(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES operators(id),state TEXT NOT NULL,notification_id TEXT,acknowledged_at INTEGER);
CREATE UNIQUE INDEX launch_readiness_outstanding ON launch_readiness(milestone_id) WHERE state='Outstanding';
CREATE TABLE launch_bulk(id TEXT PRIMARY KEY,created_at INTEGER NOT NULL,actor_id TEXT NOT NULL,expires_at INTEGER NOT NULL,undone_at INTEGER,snapshot_json TEXT NOT NULL);
CREATE TABLE launch_lens_history(id TEXT PRIMARY KEY,lens_id TEXT NOT NULL,version INTEGER NOT NULL,created_at INTEGER NOT NULL,actor_id TEXT NOT NULL,definition_json TEXT NOT NULL);
CREATE TABLE launch_analyses(id TEXT PRIMARY KEY,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,version INTEGER NOT NULL,feature TEXT NOT NULL,subject_id TEXT,lens_id TEXT,lens_draft_json TEXT,input_versions_json TEXT NOT NULL,model_call_id TEXT NOT NULL,content TEXT NOT NULL,proposed_lens_json TEXT);
CREATE TABLE launch_sample_records(installation_id TEXT NOT NULL REFERENCES sample_installations(id) ON DELETE CASCADE,table_name TEXT NOT NULL,record_id TEXT NOT NULL,original_json TEXT NOT NULL,PRIMARY KEY(installation_id,table_name,record_id));
CREATE INDEX launch_deliverable_due ON deliverables(due_date,state,campaign_id,id);
CREATE INDEX launch_milestone_campaign ON milestones(campaign_id,start_date,id);
CREATE INDEX launch_dependency_reverse ON milestone_dependencies(predecessor_id,milestone_id);
CREATE INDEX launch_risk_campaign ON risks(campaign_id,state,severity,id);
CREATE INDEX launch_decision_campaign ON decisions(campaign_id,state,id);
